/**
 * The official Flux marks, verbatim from the brand assets in web/public/brand (the Flux Brand
 * Book v2.0 artwork). GENERATED by reading those files: do not edit by hand and never redraw,
 * recolour outside blue, white, black or gray, or distort. `marks.test.ts` re-reads the SVG
 * files and fails if anything here drifts from them.
 *
 * An artboard is one official file's coordinate system. Its shapes keep the file's own element
 * order, `d` data and transforms; `group` is the accumulated transform of the enclosing <g>
 * elements. Colour is not stored here: see `variants.ts` for which file each (variant, tone)
 * is taken from and what that file fills each role with.
 */

export type ShapeRole = 'disc' | 'symbol' | 'word';

export interface MarkShape {
  role: ShapeRole;
  tag: 'path' | 'ellipse';
  /** Path data (tag path). */
  d?: string;
  /** Ellipse geometry (tag ellipse). */
  cx?: number;
  cy?: number;
  rx?: number;
  ry?: number;
  /** The element's own transform, as in the file. */
  transform?: string;
  /** The accumulated transform of the groups around it, as in the file. */
  group?: string;
}

export interface Artboard {
  /** The viewBox size of the official file. */
  w: number;
  h: number;
  shapes: readonly MarkShape[];
}

export type ArtboardId =
  | 'mark'
  | 'round-ellipse'
  | 'round-path'
  | 'lockup-ellipse'
  | 'lockup-path'
  | 'lockup-mono';

